def max_sub_array_sum_repeated(a, n, k):
    """Return the largest nonempty contiguous sum across k repetitions of a."""
    if n != len(a) or n <= 0 or k <= 0:
        raise ValueError("n must match a's positive length and k must be positive")

    current = best = a[0]
    for i in range(1, k * n):
        x = a[i % n]
        current = max(x, current + x)
        best = max(best, current)

    return best

