def max_sub_array_sum_repeated(a, n, k):
    """Return the largest non-empty contiguous subarray sum in ``a`` repeated k times.

    ``n`` must be the length of ``a``. Empty arrays and non-positive repeat
    counts are rejected because they have no non-empty subarray to maximize.
    """
    if n != len(a):
        raise ValueError("n must equal the length of a")
    if n <= 0:
        raise ValueError("a must not be empty")
    if k < 1:
        raise ValueError("k must be at least 1")

    total = 0
    prefix_sum = 0
    max_prefix = None
    best = None
    current = None

    for i in range(n):
        value = a[i]
        total += value

        prefix_sum += value
        if max_prefix is None or prefix_sum > max_prefix:
            max_prefix = prefix_sum

        if current is None:
            current = value
        else:
            current = max(value, current + value)
        if best is None or current > best:
            best = current

    if k == 1:
        return best

    suffix_sum = 0
    max_suffix = None
    for i in range(n - 1, -1, -1):
        suffix_sum += a[i]
        if max_suffix is None or suffix_sum > max_suffix:
            max_suffix = suffix_sum

    return max(best, max_suffix + max_prefix + max(0, total) * (k - 2))

def square_Sum(n):
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    return 2 * n * (n + 1) * (2 * n + 1) // 3

