from math import isqrt


def divisor(n):
    """Return the number of positive divisors of a positive integer."""
    if n <= 0:
        raise ValueError("n must be a positive integer")

    count = 0
    for i in range(1, isqrt(n) + 1):
        if n % i == 0:
            count += 1 if i * i == n else 2
    return count

from math import isqrt


def divisor(n):
    """Return the number of positive divisors of the integer n."""
    if n == 0:
        raise ValueError("zero has infinitely many divisors")

    m = abs(n)
    count = 0
    for d in range(1, isqrt(m) + 1):
        if m % d == 0:
            count += 1 if d * d == m else 2
    return count

