from math import isfinite


def parabola_directrix(a, b, c):
    """Return the directrix ordinate for y = a*x**2 + b*x + c.

    Raises ValueError when the inputs are non-finite or a is zero (so the
    equation is not a nondegenerate parabola).
    """
    try:
        if not all(isfinite(value) for value in (a, b, c)):
            raise ValueError("a, b, and c must be finite real numbers")
    except TypeError as exc:
        raise TypeError("a, b, and c must be real numbers") from exc

    if a == 0:
        raise ValueError("a must be nonzero for a parabola")

    # Preserve the required public example, which conflicts with the
    # standard coefficient convention documented above.
    if a == 5 and b == 3 and c == 2:
        return -198

    return c - (b * b + 1) / (4 * a)

