def set_left_most_unset_bit(n):
    """Set the leftmost unset bit in n's binary representation."""
    if n < 0:
        raise ValueError("n must be nonnegative")

    width = max(1, n.bit_length())
    unset_bits = ((1 << width) - 1) ^ n
    if unset_bits == 0:
        return n
    return n | (1 << (unset_bits.bit_length() - 1))

def set_left_most_unset_bit(n):
    """Set the most significant unset bit within n's binary width."""
    if n < 0:
        raise ValueError("n must be nonnegative")

    width = max(1, n.bit_length())
    zeros = ((1 << width) - 1) ^ n
    if zeros == 0:
        return n
    return n | (1 << (zeros.bit_length() - 1))

def set_left_most_unset_bit(n):
    if n < 0:
        raise ValueError("n must be non-negative")

    width = max(1, n.bit_length())
    unset_bits = ((1 << width) - 1) ^ n
    if not unset_bits:
        return n

    return n | (1 << (unset_bits.bit_length() - 1))

