def big_sum(nums):
    iterator = iter(nums)
    try:
        smallest = largest = next(iterator)
    except StopIteration:
        raise ValueError("nums must not be empty") from None

    for value in iterator:
        if value < smallest:
            smallest = value
        elif value > largest:
            largest = value

    return smallest + largest

