def next_smallest_palindrome(num):
    """Return the smallest palindrome strictly greater than the nonnegative integer num.

    Raises ValueError if num is negative.
    """
    if num < 0:
        raise ValueError("num must be nonnegative")

    s = str(num)
    n = len(s)

    if all(digit == "9" for digit in s):
        return 10**n + 1

    prefix = s[: (n + 1) // 2]
    palindrome = prefix + prefix[: n // 2][::-1]

    if palindrome <= s:
        prefix = str(int(prefix) + 1)
        palindrome = prefix + prefix[: n // 2][::-1]

    return int(palindrome)

