def next_smallest_palindrome(num):
    """Return the smallest decimal palindrome strictly greater than num."""
    if num < 0:
        return 0

    digits = str(num)
    half_length = (len(digits) + 1) // 2
    half = digits[:half_length]

    def mirror(prefix):
        suffix = prefix[:-1][::-1] if len(digits) % 2 else prefix[::-1]
        return int(prefix + suffix)

    candidate = mirror(half)
    if candidate > num:
        return candidate

    incremented_half = str(int(half) + 1)
    if len(incremented_half) > half_length:
        return 10 ** len(digits) + 1

    return mirror(incremented_half)

