def min_val(listval):
    """Return the smallest non-boolean real number in listval.

    Non-numeric values and NaN are ignored. Raise ValueError if no eligible
    values are present.
    """
    found = False
    minimum = None

    for value in listval:
        if isinstance(value, Real) and not isinstance(value, bool) and value == value:
            if not found or value < minimum:
                minimum = value
                found = True

    if not found:
        raise ValueError("min_val() requires at least one real, non-NaN value")

    return minimum

